// db_gl_distb.h - the archive of posted lines that the retired month close
// (gl_closm.cpp CreateDistBackup) wrote; spec #2 5.4 and D4.
//
// Generated by dbf2sqlite --headers-out from the real GL_DISTB.DBF, then
// hand-checked: class renamed Tgl_distb -> Tgldistb (gl_clsm.h's name), and the
// default tag is "batchno" rather than the generator's first tag "ardist"
// (FOR TYPE = 'AR'). Same tags as gl_dist.
//
// No Spec #2 screen writes it (month close is not ported); it is here so the
// header check of spec 5.4 covers every gl_dist* table.
#ifndef DB_GL_DISTB_H
#define DB_GL_DISTB_H

class Tgldistb : public Data4
{
public:
    Field4* account = nullptr;     // ACCOUNT C(7)
    Field4* dept = nullptr;        // DEPT C(4)
    Field4* period = nullptr;      // PERIOD C(4)
    Field4* date = nullptr;        // DATE C(10)
    Field4* type = nullptr;        // TYPE C(3)
    Field4* batchno = nullptr;     // BATCHNO N(6)
    Field4* reference = nullptr;   // REFERENCE C(30)
    Field4* cheque = nullptr;      // CHEQUE C(7)
    Field4* descript = nullptr;    // DESCRIPT C(40)
    Field4* debit = nullptr;       // DEBIT N(16,2)
    Field4* credit = nullptr;      // CREDIT N(16,2)

    Tgldistb(Code4* code, LPSTR = 0) : Data4(code, "gl_distb")
    {
        if (!isValid())
            return;
        SetIndex("batchno");
        top();
        account = new Field4(*this, "ACCOUNT");
        dept = new Field4(*this, "DEPT");
        period = new Field4(*this, "PERIOD");
        date = new Field4(*this, "DATE");
        type = new Field4(*this, "TYPE");
        batchno = new Field4(*this, "BATCHNO");
        reference = new Field4(*this, "REFERENCE");
        cheque = new Field4(*this, "CHEQUE");
        descript = new Field4(*this, "DESCRIPT");
        debit = new Field4(*this, "DEBIT");
        credit = new Field4(*this, "CREDIT");
    }

    ~Tgldistb()
    {
        delete account;
        delete dept;
        delete period;
        delete date;
        delete type;
        delete batchno;
        delete reference;
        delete cheque;
        delete descript;
        delete debit;
        delete credit;
    }

    Tgldistb(const Tgldistb&) = delete;
    Tgldistb& operator=(const Tgldistb&) = delete;
};

#endif
